import yaml, json
with open('registry.yaml') as f:
    reg = yaml.safe_load(f)

# Check structure
if 'experiments' in reg:
    exps = reg['experiments']
    if isinstance(exps, dict):
        match = exps.get('exec-only-s52-batch2')
        if match:
            print(json.dumps(match, indent=2, default=str))
        else:
            # search
            matches = {k: v for k, v in exps.items() if 's52' in str(k) or 'batch2' in str(k)}
            if matches:
                for k, v in matches.items():
                    print(f'=== {k} ===')
                    print(json.dumps(v, indent=2, default=str))
            else:
                keys = list(exps.keys())
                print(f'experiment keys ({len(keys)}):')
                for k in keys:
                    print(f'  {k}')
    elif isinstance(exps, list):
        matches = [e for e in exps if isinstance(e, dict) and ('exec-only-s52-batch2' in str(e.get('id','')) or 'exec-only-s52-batch2' in str(e.get('exp_id','')))]
        if matches:
            print(json.dumps(matches, indent=2, default=str))
        else:
            print(f'List of {len(exps)} experiments, sample IDs:')
            for e in exps[:5]:
                print(f'  {e.get(\"id\", e.get(\"exp_id\", \"?\"))}')
